            Copilot =>
                $"COPILOT_ALLOW_ALL= COPILOT_HOME={Out(CrossRuntimeReviewFiles.CopilotHome)} XDG_CONFIG_HOME={Out(CrossRuntimeReviewFiles.CopilotXdg)} "
